(()=>{'use strict';const C=window.CBL;
const F=(slug,cfg)=>C.register(slug,el=>C.flowLab(el,cfg));
F('dhcp',{help:'「次へ」を押して、PCが自分のネットワーク設定をもらう4段階を追います。',nodes:[['PC','まだIP設定がない'],['DHCPサーバー','設定を貸し出す']],start:'PCはネットワーク設定をまだ持っていません。',takeaway:'IPアドレスだけでなく、ゲートウェイやDNSなども自動設定できます。',steps:[
 {title:'DISCOVER',text:'PCが「設定をくれるDHCPサーバーはいますか？」と探します。',to:1,arrow:0},
 {title:'OFFER',text:'サーバーが「このIPなどを使えます」と候補を返します。',to:0,arrow:0},
 {title:'REQUEST',text:'PCが「その設定を使いたい」と要求します。',to:1,arrow:0},
 {title:'ACK',text:'サーバーが承認し、PCは設定を利用できます。',to:0,arrow:0,takeaway:'DORAの名前より「探す → 提案 → 希望 → 承認」の流れを理解できれば十分です。'}]});
F('arp',{help:'同じLANと別ネットワークを切り替え、最初に誰のMACアドレスを調べるか比べます。',defaultMode:'same',modes:{
 same:{label:'同じLAN',nodes:[['PC A','192.168.1.10'],['LAN','同じネットワーク'],['PC B','192.168.1.20']],start:'PC AはPC BのIPを知っていますが、LANで届けるためMACも必要です。',takeaway:'同じLANでは相手PCのMACをARPで調べます。',steps:[{title:'ARP Request',text:'「192.168.1.20を持つ人、MACを教えて」とLANへ問い合わせます。',to:2,arrow:1},{title:'ARP Reply',text:'PC Bが自分のMACアドレスを返します。',to:0,arrow:0}]},
 remote:{label:'別ネットワーク',nodes:[['PC A','192.168.1.10'],['ゲートウェイ','192.168.1.1'],['遠隔サーバー','203.0.113.10']],start:'宛先は別ネットワークです。PCは遠隔サーバーのMACを直接使いません。',takeaway:'遠くへ送るとき、LAN内ではまずゲートウェイのMACへ渡します。',steps:[{title:'ARP Request',text:'PC Aはゲートウェイ 192.168.1.1 のMACを調べます。',to:1,arrow:0},{title:'フレーム送信',text:'ゲートウェイのMAC宛てに渡し、その先の転送はルーターに任せます。',to:1,arrow:0}]}
}});
F('dns',{help:'まず「次へ」を押してください。名前が最終的にIPへ変わることを優先して見ます。',nodes:[['ブラウザ','www.example.com'],['DNSリゾルバ','代わりに探す'],['DNSの案内役','ルート / TLD / 権威'],['答え','203.0.113.10']],start:'ブラウザは www.example.com という名前を知っています。通信にはIPアドレスが必要です。',takeaway:'DNSの本質は「人向けの名前から、通信に使う情報を調べる」ことです。',steps:[
 {title:'問い合わせ',text:'ブラウザ側からDNSリゾルバへ名前を問い合わせます。',to:1,arrow:0},
 {title:'答えを探す',text:'キャッシュになければ、DNSの階層をたどって権威のある答えを探します。',to:2,arrow:1},
 {title:'IPが分かる',text:'www.example.com の例として 203.0.113.10 というIPが返ったとします。',to:3,arrow:2,takeaway:'ルートDNSなどの名称を暗記するより「名前 → IPが分かる」を先に持ち帰ってください。'}]});
F('tcp-udp',{help:'最初から「途中で1個落とす」ケースで比べます。TCPとUDPを切り替えてください。',defaultMode:'tcp',modes:{
 tcp:{label:'TCP',nodes:[['送信側','DATA 1 / 2'],['ネットワーク','DATA 2が消失'],['受信側','受領確認']],start:'TCPで2つのデータを送り、2個目が途中で失われる例を見ます。',takeaway:'TCPは到達・順序を扱う仕組みを持ち、必要なデータを再送できます。',steps:[{title:'DATA 1',text:'最初のデータが届きます。',to:2,arrow:1},{title:'DATA 2 消失',text:'2個目は途中で失われ、受信側に届きません。',to:1,arrow:0},{title:'再送',text:'TCPは確認情報を使い、必要なデータを再送します。',to:2,arrow:1,takeaway:'「TCPなら絶対届く」ではなく、確認・再送などで信頼性を高めます。'}]},
 udp:{label:'UDP',nodes:[['送信側','DATA 1 / 2'],['ネットワーク','DATA 2が消失'],['受信側','UDP自身は再送しない']],start:'UDPでも同じように2個目が失われる例を見ます。',takeaway:'UDP自身は到達確認・再送・順序保証を提供しません。必要ならアプリ側で補います。',steps:[{title:'DATA 1',text:'最初のデータが届きます。',to:2,arrow:1},{title:'DATA 2 消失',text:'2個目は途中で失われます。',to:1,arrow:0},{title:'そのまま',text:'UDP自身にはTCPのような再送の仕組みはありません。',to:2,arrow:1}]}
}});
F('three-way-handshake',{help:'SYNなどの名前より「お願い → 返事 → 確認」の3段階として追ってください。',nodes:[['クライアント','接続したい'],['TCP接続','確認中'],['サーバー','待ち受け']],start:'TCPではデータを本格的に送る前に、双方が通信できる状態か確認します。',takeaway:'SYN → SYN-ACK → ACKの3段階で接続を確立します。',steps:[{title:'SYN',text:'クライアントが「接続を始めたい」と送ります。',to:2,arrow:1},{title:'SYN-ACK',text:'サーバーが「受け取った。こちらも準備できる」と返します。',to:0,arrow:0},{title:'ACK',text:'クライアントが返事を確認し、接続がESTABLISHEDになります。',to:1,arrow:0}]});
F('tcp-close',{help:'正常終了の基本形を追います。実際にはACKとFINが同じセグメントになる場合もあります。',nodes:[['クライアント','ESTABLISHED'],['TCP接続','終了処理'],['サーバー','ESTABLISHED']],start:'TCP接続は、片方向ずつ「もう送らない」を伝えて正常終了できます。',takeaway:'FINは片方向の送信終了。TIME_WAITがあるだけで異常とは限りません。',steps:[{title:'FIN',text:'クライアントが「こちらからはもう送らない」とFINを送ります。',to:2,arrow:1},{title:'ACK',text:'サーバーがFINを受け取ったことを確認します。',to:0,arrow:0},{title:'FIN',text:'サーバー側も送信を終えるとFINを送ります。',to:0,arrow:0},{title:'ACK / TIME_WAIT',text:'クライアントが最後のACKを送り、しばらくTIME_WAITを経て終了します。',to:1,arrow:0,takeaway:'基本形はFIN→ACK→FIN→ACK。相手がすぐ閉じる場合はACKとFINがまとまることもあります。'}]});
F('http-https',{help:'HTTPSを「自動で見る」から始めるのがおすすめです。URLを開いて画面が出るまでを一本につなぎます。',defaultMode:'https',modes:{
 https:{label:'HTTPS',nodes:[['ブラウザ','URLを入力'],['DNS','名前→IP'],['通信路','TCP + TLS ※'],['Webサーバー','HTTP処理'],['画面','レスポンスを表示']],start:'ここではHTTP/1.1・HTTP/2でよく見るTCPベースのHTTPSを学習用に簡略化します。',takeaway:'DNSで相手を見つけ、安全な通信路を作り、HTTPの要求と応答でWebの内容を受け取ります。',steps:[{title:'DNS',text:'ホスト名から通信先IPを調べます。',to:1,arrow:0},{title:'TCP接続',text:'HTTP/1.1・HTTP/2の典型例ではTCP接続を作ります。',to:2,arrow:1},{title:'TLS',text:'HTTPSではTLSで相手を確認し、暗号化された通信路を作ります。',to:2,arrow:1},{title:'HTTP Request',text:'ブラウザがGETなどのHTTPリクエストを送ります。',to:3,arrow:2},{title:'HTTP Response',text:'サーバーがステータス・ヘッダー・内容を返し、ブラウザが表示します。',to:4,arrow:3,takeaway:'HTTP/3はTCPではなくQUICを使います。最初は「Webでは複数の仕組みが連携する」と理解すれば十分です。'}]},
 http:{label:'HTTP',nodes:[['ブラウザ','URLを入力'],['DNS','名前→IP'],['通信路','TCP'],['Webサーバー','HTTP処理'],['画面','レスポンスを表示']],start:'暗号化しないHTTPの典型的な流れを見ます。',takeaway:'HTTPはアプリケーション層の要求・応答のルールです。',steps:[{title:'DNS',text:'ホスト名からIPを調べます。',to:1,arrow:0},{title:'TCP接続',text:'HTTP/1.1の典型例ではTCP接続を作ります。',to:2,arrow:1},{title:'HTTP Request',text:'リクエストを送ります。',to:3,arrow:2},{title:'HTTP Response',text:'サーバーの応答を受けて画面を表示します。',to:4,arrow:3}]}
}});
F('tls',{help:'ClientHelloなどの名前を暗記せず「相手確認 → 鍵を作る → 暗号化」の3目的で見てください。',nodes:[['ブラウザ','接続先を確認したい'],['TLS','安全な通信路を準備'],['サーバー','証明書を提示']],start:'TCPベースのHTTPSでは、HTTPデータを送る前にTLSで安全な通信路を作ります。',takeaway:'TLSの初心者ゴールは「相手確認・鍵の確立・暗号化/改ざん検知」の3つです。',steps:[{title:'Hello / 鍵共有',text:'双方がTLSの設定や一時的な鍵共有情報を交換します。',to:2,arrow:1},{title:'証明書を検証',text:'ブラウザはホスト名・有効期限・信頼の連鎖・署名などを確認します。',to:0,arrow:0},{title:'通信鍵を導出',text:'双方が共有情報から同じ通信鍵を導出します。鍵そのものをそのまま送る、という説明ではありません。',to:1,arrow:0},{title:'暗号化通信',text:'以後のHTTPデータは導出した鍵で暗号化・認証されます。',to:1,arrow:0}]});
F('cookie-cache',{help:'CookieとCacheを切り替え、何を「覚える」のかを比べてください。',defaultMode:'cookie',modes:{
 cookie:{label:'Cookie',nodes:[['ブラウザ','Cookie保存'],['HTTP通信','Cookieヘッダー'],['サーバー','状態判断に利用']],start:'Cookieはブラウザ側に保存される小さな情報です。',takeaway:'Cookieは状態を持たせる材料。内容や使い方はサーバー側の設計で決まります。',steps:[{title:'Set-Cookie',text:'サーバーが応答でCookie保存を指示します。',to:0,arrow:0},{title:'次のRequest',text:'条件が合えばブラウザがCookieヘッダーを付けて送ります。',to:2,arrow:1}]},
 cache:{label:'Cache',nodes:[['ブラウザ','保存済みデータ'],['HTTP通信','If-None-Match'],['サーバー','ETagを確認']],start:'Cacheは同じデータを再利用して転送量や待ち時間を減らします。',takeaway:'304は「保存済み表現を再利用してよい」という応答で、通常は本文を再送しません。',steps:[{title:'初回200',text:'レスポンスとETagなどをブラウザが保存します。',to:0,arrow:0},{title:'再検証',text:'If-None-Matchなどで変更されたか確認します。',to:2,arrow:1},{title:'304',text:'変更がなければ304 Not Modified。保存済みデータを再利用します。',to:0,arrow:0}]}
}});
F('session',{help:'「ブラウザに保存するID」と「サーバー側の状態」を分けて追ってください。',nodes:[['ブラウザ','セッションCookie'],['HTTP通信','セッションID'],['Webサーバー','Session Store']],start:'HTTPの各リクエストは基本的に独立しています。Webアプリは別の仕組みでログイン状態を扱います。',takeaway:'よくあるSession方式では、CookieのセッションIDを手掛かりにサーバー側の状態を参照します。',steps:[{title:'ログイン成功',text:'サーバーがセッションを作り、ブラウザへ推測困難なセッションIDをCookieなどで渡します。',to:0,arrow:0},{title:'次のRequest',text:'ブラウザがセッションIDを送り、サーバーが有効なSessionと照合します。',to:2,arrow:1},{title:'ログイン中と判断',text:'有効なSessionなら、そのユーザーとして処理します。',to:2,arrow:1},{title:'ログアウト',text:'サーバー側Sessionを無効化し、Cookieも失効させます。',to:0,arrow:0,takeaway:'Cookieにユーザー名があるだけで「本人」と信用してはいけません。サーバー側の検証が必要です。'}]});
})();